using System;using System.IO;using System.Text;using System.Linq;using System.Diagnostics;using System.Collections.Generic;using System.Runtime.Serialization;using System.Runtime.Serialization.Json;using System.Windows.Forms;
[DataContract]internal sealed class NativeDeploymentState{
 [DataMember]public string SnapshotId,SnapshotDirectory,RuntimeDirectory,ModuleHash,Launcher,Phase;
 [DataMember]public string[] Shortcuts=new string[0];
}
internal static partial class NativeDeployment{
 internal static string Home{get{return Path.Combine(Engine.Store,"native-deployment");}}
 static string StateFile{get{return Path.Combine(Home,"state.json");}}
 internal static T Read<T>(string p){using(var f=File.OpenRead(p))return (T)new DataContractJsonSerializer(typeof(T)).ReadObject(f);}
 internal static void Write<T>(string p,T value){Directory.CreateDirectory(Path.GetDirectoryName(p));string temp=p+"."+Guid.NewGuid().ToString("N")+".tmp";using(var f=File.Create(temp))new DataContractJsonSerializer(typeof(T)).WriteObject(f,value);if(File.Exists(p))File.Replace(temp,p,null);else File.Move(temp,p);}
 internal static NativeDeploymentState Current{get{return File.Exists(StateFile)?Read<NativeDeploymentState>(StateFile):null;}}
 internal static string Capture(Theme theme,string wallpaperOverride=null,bool overrideWallpaper=false){
  Palette.Validate(theme);string id=DateTime.UtcNow.ToString("yyyyMMddTHHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8),dir=Path.Combine(Home,"snapshots",id);Directory.CreateDirectory(dir);
  try{Engine.Save(Path.Combine(dir,"theme-active.json"),theme.Copy());foreach(string key in ThemeTransfer.Keys){string from=Path.Combine(Engine.Store,key),to=Path.Combine(dir,key);if(!File.Exists(from))continue;Directory.CreateDirectory(Path.GetDirectoryName(to));File.Copy(from,to);}
   string source=overrideWallpaper?wallpaperOverride:AutoBackground.SavedImage();if(!overrideWallpaper&&File.Exists(Path.Combine(Engine.Store,"background.txt"))&&source==null)throw new IOException("保存的壁纸无效，不能静默导出成无壁纸方案。");if(source!=null){string wall=Path.Combine(dir,"backgrounds",Engine.Hash(File.ReadAllBytes(source))+".png");Directory.CreateDirectory(Path.GetDirectoryName(wall));File.Copy(source,wall);File.WriteAllText(Path.Combine(dir,"background.txt"),wall,Encoding.UTF8);}
   NormalizeProfiles(dir);ThemeTransfer.Export(Path.Combine(dir,"approved.wxtheme"),theme,dir);
   string digest=Engine.Hash(File.ReadAllBytes(Path.Combine(dir,"approved.wxtheme")));File.WriteAllText(Path.Combine(dir,"snapshot.sha256"),digest,Encoding.ASCII);
   Write(Path.Combine(Home,"draft.json"),new NativeDeploymentState{SnapshotId=id,SnapshotDirectory=dir,Phase="captured"});return dir;
  }catch{File.WriteAllText(Path.Combine(dir,"incomplete.txt"),"Capture failed; never activate this directory.");throw;}
 }
 internal static void VerifySnapshot(string dir){if(File.Exists(Path.Combine(dir,"incomplete.txt")))throw new IOException("方案保存不完整。");string zip=Path.Combine(dir,"approved.wxtheme");if(Engine.Hash(File.ReadAllBytes(zip))!=File.ReadAllText(Path.Combine(dir,"snapshot.sha256")).Trim())throw new IOException("方案校验失败。");var draft=ThemeTransfer.Read(zip);var saved=Engine.Load(Path.Combine(dir,"theme-active.json"));if(Palette.Pack(draft.Theme)!=Palette.Pack(saved))throw new IOException("方案颜色与快照不一致。");foreach(var pair in draft.Settings)if(!File.ReadAllBytes(Path.Combine(dir,pair.Key)).SequenceEqual(pair.Value))throw new IOException("方案设置已更改，请重新保存快照。");if((draft.Wallpaper!=null)!=File.Exists(Path.Combine(dir,"background.txt")))throw new IOException("方案壁纸与已确认内容不一致。");if(File.Exists(Path.Combine(dir,"snapshot-format.txt")))foreach(string mode in new[]{"light","dark"})foreach(string key in AppearanceProfiles.Keys.Where(k=>k!="input-glass.txt"))if(!File.Exists(Path.Combine(dir,"appearance-"+mode,key)))throw new IOException("方案配置不完整："+mode+"/"+key);if(draft.Wallpaper!=null){string wall=File.ReadAllText(Path.Combine(dir,"background.txt")).Trim();if(!File.ReadAllBytes(wall).SequenceEqual(draft.Wallpaper))throw new IOException("方案壁纸已更改。");}}
 static string Quote(string s){if(s.IndexOf('"')>=0)throw new ArgumentException("路径不能含引号。");return "\""+s.TrimEnd('\\')+"\"";}
 internal static NativeDeploymentState Prepare(string snapshot,string bundle){
  VerifySnapshot(snapshot);string module=Path.Combine(bundle,"qttestability.dll"),hash=File.ReadAllText(Path.Combine(bundle,"module.sha256")).Trim();if(Engine.Hash(File.ReadAllBytes(module))!=hash)throw new IOException("原生模块包校验失败。");
  string id=Path.GetFileName(snapshot),runtime=Path.Combine(Home,"versions",id);Directory.CreateDirectory(runtime);File.Copy(module,Path.Combine(runtime,"qttestability.dll"),true);File.WriteAllText(Path.Combine(runtime,"module.sha256"),hash,Encoding.ASCII);
  string launcher=Path.Combine(runtime,"微信主题启动器.exe");File.Copy(Application.ExecutablePath,launcher,true);
  var p=new ProcessStartInfo(Application.ExecutablePath,"--native-export "+Quote(runtime)+" "+Quote(snapshot)){UseShellExecute=false,CreateNoWindow=true};using(var child=Process.Start(p)){if(!child.WaitForExit(60000))throw new IOException("方案编译超时，未启用新方案。");if(child.ExitCode!=0)throw new IOException("方案编译失败，未启用新方案。");}
  // The compiler subprocess uses the original app's SVG assets; runtime only reads prepared files.
  var state=new NativeDeploymentState{SnapshotId=id,SnapshotDirectory=snapshot,RuntimeDirectory=runtime,ModuleHash=hash,Launcher=launcher,Phase="prepared"};Write(Path.Combine(runtime,"deployment.json"),state);Write(Path.Combine(Home,"prepared.json"),state);return state;
 }
 internal static void Activate(NativeDeploymentState state,string shortcutDirectory){
  Engine.RequireStopped();VerifySnapshot(state.SnapshotDirectory);if(Engine.Hash(File.ReadAllBytes(Path.Combine(state.RuntimeDirectory,"qttestability.dll")))!=state.ModuleHash)throw new IOException("模块校验失败。");
  // A dedicated launch entry is explicit and reversible. Direct Weixin.exe launches bypass it.
  Directory.CreateDirectory(shortcutDirectory);string link=Path.Combine(shortcutDirectory,"微信（主题模式）.lnk");if(File.Exists(link))throw new IOException("主题启动入口已存在，请先停用旧方案；不会覆盖其他快捷方式。");
  object shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell")),item=null;try{item=shell.GetType().InvokeMember("CreateShortcut",System.Reflection.BindingFlags.InvokeMethod,null,shell,new object[]{link});foreach(var pair in new[]{new[]{"TargetPath",state.Launcher},new[]{"Arguments","--native-launch"},new[]{"WorkingDirectory",state.RuntimeDirectory},new[]{"IconLocation",Engine.Exe+",0"},new[]{"Description","微信进程内主题；调色室无需常驻"}})item.GetType().InvokeMember(pair[0],System.Reflection.BindingFlags.SetProperty,null,item,new object[]{pair[1]});item.GetType().InvokeMember("Save",System.Reflection.BindingFlags.InvokeMethod,null,item,null);}finally{if(item!=null)System.Runtime.InteropServices.Marshal.FinalReleaseComObject(item);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}
  state.Shortcuts=new[]{link};state.Phase="active";Write(Path.Combine(state.RuntimeDirectory,"deployment.json"),state);Write(StateFile,state);AutoBackground.SetEnabled(false);
 }
 internal static void StartPreparedTest(NativeDeploymentState state){Engine.RequireStopped();if(AutoBackground.Enabled)throw new IOException("请先在启动与恢复中停用旧外置后台。");VerifySnapshot(state.SnapshotDirectory);var p=new ProcessStartInfo(state.Launcher,"--native-test-launch"){UseShellExecute=false,CreateNoWindow=true};using(var child=Process.Start(p)){if(!child.WaitForExit(30000)||child.ExitCode!=0)throw new IOException("测试启动失败；请导出诊断报告。");}AppLog.Event("NATIVE","Test launch requested; snapshot="+state.SnapshotId);}
 internal static void StopPreparedTest(){Engine.RequireStopped();string file=Path.Combine(Home,"prepared.json");if(!File.Exists(file))return;var state=Read<NativeDeploymentState>(file);var active=Current;if(state.Phase=="active"||(active!=null&&active.Phase=="active"&&active.SnapshotId==state.SnapshotId))throw new IOException("此方案已正式启用，请使用停用进程内方案。");string config=Path.Combine(state.RuntimeDirectory,"runtime.ini");if(File.Exists(config)){string text=File.ReadAllText(config);File.WriteAllText(config,text.Replace("enabled=1","enabled=0"),Encoding.Unicode);}state.Phase="disabled";Write(Path.Combine(state.RuntimeDirectory,"deployment.json"),state);Write(file,state);AppLog.Event("NATIVE","Prepared test disabled; original Weixin entry unchanged");}
 internal static void Disable(){Engine.RequireStopped();var state=Current;if(state==null)return;foreach(string link in state.Shortcuts){if(Path.GetFileName(link)!="微信（主题模式）.lnk")throw new IOException("拒绝移除未知启动入口。");if(File.Exists(link))File.Delete(link);}state.Phase="disabled";Write(Path.Combine(state.RuntimeDirectory,"deployment.json"),state);Write(StateFile,state);}
 internal static int Launch(bool test=false){string dir=AppDomain.CurrentDomain.BaseDirectory;var state=Read<NativeDeploymentState>(Path.Combine(dir,"deployment.json"));if(state.Phase!="active"&&!(test&&state.Phase=="prepared"))throw new IOException("此方案尚未启用或已经停用。");if(AutoBackground.Enabled)throw new IOException("请先在启动与恢复中停用旧外置后台，再从主题入口启动。");VerifySnapshot(state.SnapshotDirectory);if(Engine.Hash(File.ReadAllBytes(Path.Combine(dir,"qttestability.dll")))!=state.ModuleHash)throw new IOException("模块校验失败。");NativeBackground.ValidateDeploymentTarget();if(Process.GetProcessesByName("Weixin").Length!=0)throw new IOException("微信已经运行；本次不会向现有进程重复加载主题。");var p=new ProcessStartInfo(Engine.Exe,"--scene=taskbarpins"){UseShellExecute=false,WorkingDirectory=Path.GetDirectoryName(Engine.Exe)};p.EnvironmentVariables["QT_LOAD_TESTABILITY"]="1";p.EnvironmentVariables["PATH"]=dir+Path.PathSeparator+(Environment.GetEnvironmentVariable("PATH")??"");Process.Start(p);AppLog.Event("NATIVE",test?"Test session launched; no startup entry installed":"Deployed session launched");return 0;}
}
internal static partial class NativeBackground{internal static void ValidateDeploymentTarget(){ValidateFile();if(Engine.Hash(File.ReadAllBytes(Engine.Target))!=Engine.OriginalHash)throw new IOException("进程内模块仅适配原版微信 4.1.15.56 x64。");}}
